{"implementation":"def solve(case):
    payload = case['payload']
    initial = payload['initial_state']
    max_steps = payload['max_steps']
    tool_obs = payload['tool_observations']
    trans = payload['transitions']
    trace = []
    cur = initial
    steps = 0
    while steps < max_steps:
        if cur not in trans:
            return {"status": "error", "final_value": None, "trace": trace}
        st = trans[cur]
        if st['kind'] == 'final':
            return {"status": "completed", "final_value": st['value'], "trace": trace}
        tool = st['action']
        obs = tool_obs.get(tool, "invalid")
        trace.append({"action": tool, "observation": obs})
        steps += 1
        nxt = st.get('next_by_observation', {}).get(obs, st.get('default_next'))
        cur = nxt
    if cur in trans and trans[cur]['kind'] == 'final':
        return {"status": "completed", "final_value": trans[cur]['value'], "trace": trace}
    return {"status": "max_steps_exceeded", "final_value": None, "trace": trace}"}
